import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"スラッシュコマンド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/slash-commands.md","filePath":"ja/guides/slash-commands.md","lastUpdated":1792323081000}'),c={name:"ja/guides/slash-commands.md"};function s(r,t,l,n,i,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="スラッシュコマンド" tabindex="-1">スラッシュコマンド <a class="header-anchor" href="#スラッシュコマンド" aria-label="Permalink to &quot;スラッシュコマンド&quot;">​</a></h1><p>Memoh は <strong>スラッシュコマンド</strong> に対応しています。コマンドは LLM に届く前にインターセプトされ、ステータスの確認、設定の変更、モデルの切り替え、セッションの作成、生成の停止などを手早く行えます。外部チャネルでも内蔵のウェブチャットでも使えます。<strong>コマンドの解析自体にモデルの token は基本的に消費されません</strong>（実際に会話へ入る内容とは別の話です）。</p><hr><h2 id="コマンドの形" tabindex="-1">コマンドの形 <a class="header-anchor" href="#コマンドの形" aria-label="Permalink to &quot;コマンドの形&quot;">​</a></h2><p>ほとんどのコマンドは「リソース / アクション / 引数」の形をとります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/resource [action] [arguments...]</span></span></code></pre></div><p>例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule list</span></span>\n<span class="line"><span>/model current</span></span>\n<span class="line"><span>/schedule create morning-news &quot;0 9 * * *&quot; &quot;Send a daily summary&quot;</span></span></code></pre></div><p>ポイント：</p><ul><li><strong>resource</strong> はグループです。<code>schedule</code>、<code>model</code>、<code>status</code> など。</li><li><strong>action</strong> は具体的なサブコマンドです。<code>list</code>、<code>get</code>、<code>set</code> など。</li><li><strong>arguments</strong> は action の後ろに置きます。スペースを含む値は引用符で囲みます。</li><li>グループによっては<strong>デフォルトアクション</strong>があります。たとえば <code>/settings</code> は <code>/settings get</code> と、<code>/status</code> は <code>/status show</code> と同じです。</li></ul><p>このほかに <strong>トップレベル</strong> のコマンドが 2 つあります。</p><ul><li><code>/new</code>：現在の会話ルートに新しいセッションを開く</li><li><code>/stop</code>：現在のスレッドで進行中の生成を止める</li></ul><hr><h2 id="スキルの起動とクイックアクション" tabindex="-1">スキルの起動とクイックアクション <a class="header-anchor" href="#スキルの起動とクイックアクション" aria-label="Permalink to &quot;スキルの起動とクイックアクション&quot;">​</a></h2><p>固定コマンドのほかに、スラッシュで Bot の <a href="./skills.html">スキル</a> を必要なときに起動できます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/&lt;スキル名&gt; [任意のプロンプト]</span></span></code></pre></div><ul><li><strong>ウェブのコンポーザー</strong> で <code>/</code> を入力するとパネルが開きます。<strong>クイックアクション</strong>（<code>/help</code>、<code>/skill list</code>、<code>/new</code>、<code>/compact</code>、<code>/model</code>）に加えて、Bot のスキル一覧が表示されます。選んだスキルは取り外せるチップになります。上の形式を直接打ち込んでもかまいません。</li><li><strong>IM チャネル</strong> でも同じ <code>/&lt;スキル名&gt;</code> の形が使えます。<code>/skill list</code> はタップできるボタンとして表示されます。</li><li>起動したスキルの内容が注入されるのは<strong>現在のターンだけ</strong>です。履歴にも、セッションタイトルにも、メモリにも残りません。</li></ul><p>スキル名は送信のたびに、Bot で現在有効なスキルカタログに対して<strong>サーバー側</strong>で解決されます。コマンドやスキルのように見えてどちらにも一致しないスラッシュ入力は、モデルに流れることなく明確なエラーになります。先頭が <code>/</code> なだけの普通のテキスト（パスや URL）は、これまでどおりチャットとして扱われます。</p><p>制限が 2 つあります。</p><ul><li>スキル起動のメッセージには添付ファイルを付けられません（固定コマンドは添付ファイル付きでもそのまま実行されます）。</li><li>グループチャットでは、Bot に向けられていないスラッシュメッセージは黙って無視されます。</li></ul><h2 id="組み込みヘルプ" tabindex="-1">組み込みヘルプ <a class="header-anchor" href="#組み込みヘルプ" aria-label="Permalink to &quot;組み込みヘルプ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コマンド</th><th>内容</th></tr></thead><tbody><tr><td><code>/help</code></td><td>トップレベルのコマンド一覧</td></tr><tr><td><code>/help &lt;group&gt;</code></td><td>グループ内にどんな action があるか</td></tr><tr><td><code>/help &lt;group&gt; &lt;action&gt;</code></td><td>特定の action の使い方</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/help</span></span>\n<span class="line"><span>/help model</span></span>\n<span class="line"><span>/help model set</span></span></code></pre></div><p><strong>現在のバージョン</strong> が実際にどのコマンドに対応しているかを調べる、いちばん速い方法です。</p><hr><h2 id="解析ルール" tabindex="-1">解析ルール <a class="header-anchor" href="#解析ルール" aria-label="Permalink to &quot;解析ルール&quot;">​</a></h2><ul><li>グループでは <strong>@Bot プレフィックス</strong> が使えます。例：<code>@BotName /help</code>。</li><li><strong>Telegram</strong> では bot サフィックスを付けられます。例：<code>/help@MemohBot</code>。</li><li>引用符で囲むと 1 つの引数として扱われます。例：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule create morning-news &quot;0 9 * * *&quot; &quot;Send today&#39;s top stories&quot;</span></span></code></pre></div><p>行全体が既知のコマンドに<strong>一致しない</strong>場合は、スラッシュコマンドではなく普通のチャットとして送られます。</p><hr><h2 id="権限" tabindex="-1">権限 <a class="header-anchor" href="#権限" aria-label="Permalink to &quot;権限&quot;">​</a></h2><p>読み取り系は、Bot と話せる人なら基本的に使えます。<br><code>set</code>、<code>create</code>、<code>update</code>、<code>delete</code>、<code>enable</code>、<code>disable</code> などの書き込み操作の多くは <strong>owner</strong> が必要です。</p><p><code>/help</code> の出力では、owner 専用のものに <code>[owner]</code> が付きます。</p><hr><h2 id="クイックリファレンス" tabindex="-1">クイックリファレンス <a class="header-anchor" href="#クイックリファレンス" aria-label="Permalink to &quot;クイックリファレンス&quot;">​</a></h2><h3 id="トップレベル" tabindex="-1">トップレベル <a class="header-anchor" href="#トップレベル" aria-label="Permalink to &quot;トップレベル&quot;">​</a></h3><table tabindex="0"><thead><tr><th>コマンド</th><th>説明</th></tr></thead><tbody><tr><td><code>/help</code></td><td>ヘルプ</td></tr><tr><td><code>/new</code>（任意で <code>chat</code> / <code>discuss</code>）</td><td>新しいセッション</td></tr><tr><td><code>/stop</code></td><td>進行中の生成を停止</td></tr></tbody></table><h3 id="リソースグループ" tabindex="-1">リソースグループ <a class="header-anchor" href="#リソースグループ" aria-label="Permalink to &quot;リソースグループ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>グループ</th><th>説明</th><th>デフォルトアクション</th></tr></thead><tbody><tr><td><code>/schedule</code></td><td>スケジュールタスク</td><td>なし</td></tr><tr><td><code>/mcp</code></td><td>MCP 接続の確認</td><td>なし</td></tr><tr><td><code>/settings</code></td><td>Bot の設定</td><td><code>get</code></td></tr><tr><td><code>/model</code></td><td>チャットモデル</td><td>なし</td></tr><tr><td><code>/memory</code></td><td>メモリプロバイダー</td><td>なし</td></tr><tr><td><code>/search</code></td><td>ウェブ検索プロバイダー</td><td>なし</td></tr><tr><td><code>/usage</code></td><td>token 使用量</td><td><code>summary</code></td></tr><tr><td><code>/email</code></td><td>メールプロバイダー、バインディング、送信トレイ</td><td>なし</td></tr><tr><td><code>/skill</code></td><td>スキル一覧</td><td><code>list</code></td></tr><tr><td><code>/fs</code></td><td>ワークスペースのファイル</td><td>なし</td></tr><tr><td><code>/status</code></td><td>セッションのメッセージ/コンテキスト/キャッシュ</td><td><code>show</code></td></tr><tr><td><code>/access</code></td><td>アイデンティティと ACL</td><td><code>show</code></td></tr><tr><td><code>/compact</code></td><td><strong>セッション</strong> のコンテキスト圧縮を即時実行</td><td><code>run</code></td></tr><tr><td><code>/context</code></td><td>現在のセッションのコンテキストウィンドウ使用量</td><td><code>show</code></td></tr><tr><td><code>/reasoning</code>（エイリアス <code>/reason</code>、<code>/effort</code>、<code>/think</code>）</td><td>このセッションの推論レベルを表示・設定</td><td><code>show</code></td></tr><tr><td><code>/language</code></td><td>コマンド UI の言語を表示・設定（<code>auto</code>、<code>en</code>、<code>zh</code>、<code>ja</code>）</td><td><code>show</code></td></tr><tr><td><code>/link &lt;code&gt;</code></td><td>アプリで生成したコードで、現在のチャネルアカウントを Memoh ユーザーに紐付け</td><td><code>consume</code></td></tr></tbody></table><hr><h2 id="セッション系コマンド" tabindex="-1">セッション系コマンド <a class="header-anchor" href="#セッション系コマンド" aria-label="Permalink to &quot;セッション系コマンド&quot;">​</a></h2><h3 id="new" tabindex="-1"><code>/new</code> <a class="header-anchor" href="#new" aria-label="Permalink to &quot;`/new`&quot;">​</a></h3><p><strong>現在の会話ルート</strong> に新しいセッションを開きます。古い履歴は残ったまま、新しい現在のコンテキストに切り替わるだけです。</p><ul><li><code>/new</code>：現在の場面のデフォルトタイプで作成</li><li><code>/new chat</code>：chat を強制</li><li><code>/new discuss</code>：discuss を強制</li></ul><p>デフォルトでは、内蔵ウェブチャットは多くが <code>chat</code>、ダイレクトメッセージは多くが <code>chat</code>、外部チャネルのグループは多くが <code>discuss</code> です。</p><p><strong>内蔵のウェブチャット</strong> に <code>/new discuss</code> はありません。discuss を使うには Telegram や Discord などを使ってください。</p><p>詳細は <a href="./sessions.html">セッション</a> を参照してください。</p><h3 id="stop" tabindex="-1"><code>/stop</code> <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;`/stop`&quot;">​</a></h3><p><strong>現在のスレッド</strong> で進行中の生成を止めます。ストリーミングの内容がもう十分なとき、ツールの処理が長引きすぎているとき、次の発言の前に割り込みたいときに向いています。</p><hr><h2 id="ステータスと調査" tabindex="-1">ステータスと調査 <a class="header-anchor" href="#ステータスと調査" aria-label="Permalink to &quot;ステータスと調査&quot;">​</a></h2><h3 id="status" tabindex="-1"><code>/status</code> <a class="header-anchor" href="#status" aria-label="Permalink to &quot;`/status`&quot;">​</a></h3><p>現在のセッションレベルの情報です。メッセージ数、コンテキスト使用量、キャッシュヒット、読み書き token、このスレッドで使ったスキルなど。</p><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th></tr></thead><tbody><tr><td><code>show</code></td><td><code>/status</code> または <code>/status show</code>。現在のルートが対象</td></tr><tr><td><code>latest</code></td><td>現在のルートにアクティブなセッションがないとき、<strong>その Bot の最新</strong> セッションを見るのに使う</td></tr></tbody></table><h3 id="access" tabindex="-1"><code>/access</code> <a class="header-anchor" href="#access" aria-label="Permalink to &quot;`/access`&quot;">​</a></h3><p>現在のチャネルアイデンティティ、紐付いたユーザー、ロール、書き込みコマンドの可否、チャネル/会話/thread のスコープ、ACL の評価結果を表示します。紐付けや ACL、書き込みコマンドが拒否された理由を調べるときに使います。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/access</span></span></code></pre></div><h3 id="usage" tabindex="-1"><code>/usage</code> <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;`/usage`&quot;">​</a></h3><p>直近 7 日間の token 使用量です。</p><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th></tr></thead><tbody><tr><td><code>summary</code></td><td><code>/usage</code> または <code>/usage summary</code></td></tr><tr><td><code>by-model</code></td><td><code>/usage by-model</code></td></tr></tbody></table><h3 id="email" tabindex="-1"><code>/email</code> <a class="header-anchor" href="#email" aria-label="Permalink to &quot;`/email`&quot;">​</a></h3><p>現在の Bot のメールプロバイダー、バインディング、送信トレイです。</p><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th></tr></thead><tbody><tr><td><code>providers</code></td><td><code>/email providers</code></td></tr><tr><td><code>bindings</code></td><td><code>/email bindings</code></td></tr><tr><td><code>outbox</code></td><td><code>/email outbox</code></td></tr></tbody></table><hr><h2 id="設定系コマンド" tabindex="-1">設定系コマンド <a class="header-anchor" href="#設定系コマンド" aria-label="Permalink to &quot;設定系コマンド&quot;">​</a></h2><h3 id="settings" tabindex="-1"><code>/settings</code> <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;`/settings`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th><th>権限</th></tr></thead><tbody><tr><td><code>get</code></td><td><code>/settings</code> または <code>/settings get</code></td><td>全員</td></tr><tr><td><code>update</code></td><td><code>/settings update [options]</code></td><td>Owner</td></tr></tbody></table><p><code>update</code> の主なオプション：</p><table tabindex="0"><thead><tr><th>オプション</th><th>説明</th></tr></thead><tbody><tr><td><code>--language</code></td><td><code>en</code>、<code>zh</code> など</td></tr><tr><td><code>--acl_default_effect</code></td><td><code>allow</code> / <code>deny</code></td></tr><tr><td><code>--reasoning_effort</code></td><td><code>low</code> / <code>medium</code> / <code>high</code> / <code>xhigh</code> などのレベル。実際に使える値は、選択中のモデルが宣言している reasoning efforts によります</td></tr><tr><td><code>--chat_model_id</code></td><td>チャットモデルの UUID</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/settings update --language en --reasoning_effort high</span></span></code></pre></div><h3 id="model" tabindex="-1"><code>/model</code> <a class="header-anchor" href="#model" aria-label="Permalink to &quot;`/model`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th><th>権限</th></tr></thead><tbody><tr><td><code>list [provider_name]</code></td><td><code>/model list</code></td><td>全員</td></tr><tr><td><code>current</code></td><td><code>/model current</code></td><td>全員</td></tr><tr><td><code>set</code></td><td><code>/model set &lt;model_id&gt;</code> または <code>/model set &lt;provider_name&gt; &lt;model_name&gt;</code></td><td>Owner</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/model list</span></span>\n<span class="line"><span>/model list OpenAI</span></span>\n<span class="line"><span>/model current</span></span>\n<span class="line"><span>/model set gpt-4o</span></span>\n<span class="line"><span>/model set OpenAI gpt-4o</span></span></code></pre></div><h3 id="memory" tabindex="-1"><code>/memory</code> <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;`/memory`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th><th>権限</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/memory list</code></td><td>全員</td></tr><tr><td><code>current</code></td><td><code>/memory current</code></td><td>全員</td></tr><tr><td><code>set</code></td><td><code>/memory set &lt;name&gt;</code></td><td>Owner</td></tr></tbody></table><h3 id="search" tabindex="-1"><code>/search</code> <a class="header-anchor" href="#search" aria-label="Permalink to &quot;`/search`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th><th>権限</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/search list</code></td><td>全員</td></tr><tr><td><code>current</code></td><td><code>/search current</code></td><td>全員</td></tr><tr><td><code>set</code></td><td><code>/search set &lt;name&gt;</code></td><td>Owner</td></tr></tbody></table><h3 id="mcp" tabindex="-1"><code>/mcp</code> <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;`/mcp`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th><th>権限</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/mcp list</code></td><td>全員</td></tr><tr><td><code>get</code></td><td><code>/mcp get &lt;name&gt;</code></td><td>全員</td></tr><tr><td><code>delete</code></td><td><code>/mcp delete &lt;name&gt;</code></td><td>Owner</td></tr></tbody></table><hr><h2 id="自動化とファイル" tabindex="-1">自動化とファイル <a class="header-anchor" href="#自動化とファイル" aria-label="Permalink to &quot;自動化とファイル&quot;">​</a></h2><h3 id="schedule" tabindex="-1"><code>/schedule</code> <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;`/schedule`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th><th>権限</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/schedule list</code></td><td>全員</td></tr><tr><td><code>get</code></td><td><code>/schedule get &lt;name&gt;</code></td><td>全員</td></tr><tr><td><code>create</code></td><td><code>/schedule create &lt;name&gt; &lt;pattern&gt; &lt;command&gt;</code></td><td>Owner</td></tr><tr><td><code>update</code></td><td><code>/schedule update &lt;name&gt; [--pattern P] [--command C]</code></td><td>Owner</td></tr><tr><td><code>delete</code></td><td><code>/schedule delete &lt;name&gt;</code></td><td>Owner</td></tr><tr><td><code>enable</code></td><td><code>/schedule enable &lt;name&gt;</code></td><td>Owner</td></tr><tr><td><code>disable</code></td><td><code>/schedule disable &lt;name&gt;</code></td><td>Owner</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule list</span></span>\n<span class="line"><span>/schedule create morning-news &quot;0 9 * * *&quot; &quot;Summarize today&#39;s top tech news&quot;</span></span>\n<span class="line"><span>/schedule disable morning-news</span></span></code></pre></div><h3 id="skill" tabindex="-1"><code>/skill</code> <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;`/skill`&quot;">​</a></h3><p><strong>実行時に使える</strong> スキルだけを一覧します。無効化されたソースやシャドーイングされたソースは表示されません。</p><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/skill</code> または <code>/skill list</code></td></tr></tbody></table><p>ターン単位でスキルを起動するには <code>/&lt;スキル名&gt; [プロンプト]</code> を使います。上の <a href="#スキルの起動とクイックアクション">スキルの起動とクイックアクション</a> を参照してください。</p><h3 id="fs" tabindex="-1"><code>/fs</code> <a class="header-anchor" href="#fs" aria-label="Permalink to &quot;`/fs`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/fs list [path]</code></td></tr><tr><td><code>read</code></td><td><code>/fs read &lt;path&gt;</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/fs list /</span></span>\n<span class="line"><span>/fs list /home</span></span>\n<span class="line"><span>/fs read /home/bot/IDENTITY.md</span></span></code></pre></div><p>ファイルが大きすぎる場合、出力は途中で切り捨てられます。</p><hr><h2 id="compact" tabindex="-1"><code>/compact</code> <a class="header-anchor" href="#compact" aria-label="Permalink to &quot;`/compact`&quot;">​</a></h2><p><strong>現在のセッション</strong> に対して <a href="./compaction.html">セッションコンテキスト圧縮</a> を即時に実行します。メモリストアのエントリーを書き換えるメモリ圧縮<strong>ではありません</strong>。</p><table tabindex="0"><thead><tr><th>アクション</th><th>使い方</th></tr></thead><tbody><tr><td><code>run</code></td><td><code>/compact</code> または <code>/compact run</code></td></tr></tbody></table><p>会話が長くなり、先に要約してから続けたいときに役立ちます。</p>',97)])])}const b=e(c,[["render",s]]);export{u as __pageData,b as default};
